     "a": "姐姐懂。看著本金只剩下20%，那种心痛、自责、不甘，全都搅在一起，压得人喘不过气。\n\n但姐姐想问你一个很关键的问题：你现在的第一反应，是想把剩下的20%拿去赌一把，还是想先让它不再变少？\n\n如果是前者，姐姐要跟你说句真心话：你还没从这场亏损里走出来。你的大脑还在“复仇模式”里，想用一把重仓把失去的全都捞回来。但你想过没有，从80%亏到90%，和从80%赚回100%，这两条路，哪条更容易？\n\n很多人意识不到，前者只需要一次冲动，后者需要你彻底改变自己。\n\n所以姐姐给你的第一个建议，不是怎么翻本，而是先停下来。先承认这80%已经亏掉了，它不再是你的钱，而是你交给市场的学费。学费交了，你就得学到东西，不然就白交了。\n\n你要问自己一个问题：这80%是怎么亏掉的？是扛单扛没的，是频繁交易磨没的，还是重仓梭哈一把亏没的？找到这个死穴，你这笔学费才没白交。\n\n然后，把剩下的20%当成一颗种子。你现在要做的，不是把种子煮熟吃了填肚子，而是把它种进土里，用规则、纪律、风控去浇灌它，让它慢慢长回去。\n\nDCOGAI替不了你去翻本，但它能替你在最容易犯错的时候管住手。在你又想重仓的时候，仓位限制替你拦著；在你又舍不得止损的时候，自动纠错替你砍了；在你连续亏损心态崩了想乱做的时候，休眠替你强制冷静。\n\n把剩下的20%交给规则，让它替你在失控的边缘踩刹车。你先让自己活下来，再慢慢想怎么把曾经失去的，一点一点拿回来。",
