     "q": "行情这么好，系统为什么一直休眠不动？",
     "a": "姐姐懂你现在的感觉。看著行情在动，别的币在涨，你的账户却一动不动，心里那个急，像猫抓一样。有个声音一直在脑子里转：“怎么不动啊？再不动就真错过了！”\n\n但你回忆一下，过去你亏得最惨、最后悔的那些单子，是不是大多都在你觉得“行情好得不得了”、怕错过、赶紧追进去的时候？\n\n市场就是这样，它最热闹、最诱人的时候，往往也最容易让人上头犯错。\n\n系统选择休眠，不是它看不见行情在涨，而是它用冷冰冰的规则判断，现在的行情，性价比不高，不值得你冒险。它是在替你忍，替你挡住那个因为焦虑而总想冲进去的自己。\n\n你看，真正厉害的猎手，大部分时间都不是在开枪，而是在潜伏。他在等一个十拿九稳、能一击命中的机会。现在的不动，就是为了把子弹省下来，留给那个真正值得的时刻。\n\n所以，别急。让它替你把这道门守好。咱们不抢每一次反弹，只拿那些确定性最高的机会。忍住这一次，你就比那些在热闹中迷失的人，又强大了一分。",
