     "id": "c5",
     "q": "你们是不是骗子？",
     "a": "姐姐觉得，在币圈问这个问题，太正常了。甚至可以说，不问才不正常。\n\n我不跟你拍胸脯保证“我们绝对靠谱”，那种话你听多了，反而更慌。我只跟你说三件事，你自己判断。\n\n第一，骗子最怕你试，因为他的东西是假的，一试就穿帮。我们敢让你免费试用一整年，所有功能全开。因为我们不怕你试，就怕你不试。如果一年下来没帮你赚到钱，这一年我们就白给你用，一分不收。\n\n第二，骗子想方设法让你把钱交到他手里。我们正好相反。你的钱从头到尾都在你自己的交易所账户里。我们只通过API连接交易权限，提现和划转的权限你自己关掉，我们根本碰不到你的资金。\n\n第三，骗子什么都敢承诺，“稳赚”、“翻倍”，你想听什么他就说什么。我们不敢。我们会直接告诉你，没办法稳赚，没办法预测行情。我们只能帮你管住手、帮你纠错、帮你控制风险，让你活得更久。这话不诱人，但这是实话。\n\n所以，你可以继续怀疑，也应该继续怀疑。然后用这一年的免费试用期，慢慢看，慢慢感受。让时间和你的账户，自己告诉你答案。",
