     "id": "c8",
     "q": "我天天盯盘，累得要死，结果越盯越亏，怎么办？",
     "a": "你这个问题问到点子上了。我跟你说实话，盯盘是这个世界上最没用、但又最让人上瘾的事。\n\n为什么没用？因为你盯不盯，K线都会走。你看它涨，你激动；你看它跌，你害怕。然后你就开始操作——涨了追，跌了割，来回打脸。最后你会发现，你不操作的时候，账户反而更稳。\n\n这就是盯盘最大的害处：它让你觉得自己必须做点什么。但交易这件事，有时候做得多错得多，不做反而赢了。\n\n你有没有发现，你亏钱最多的日子，往往是你盯盘最久的日子？因为你被每一根K线牵著鼻子走，情绪一上来，什么计划、什么纪律，全忘了。\n\nDCOGAI 的休眠功能，说白了就是替你关掉那个让你手痒的屏幕。行情不好的时候，它直接休息，不开单。不是没行情，是行情不值得做。它帮你忍住那些\"不做就难受\"的冲动，帮你省下那些被手续费和滑点慢慢磨掉的本金。\n\n你想想，农民种地，冬天也要休息，等春天再播种。交易也是一样。市场大多数时候是\"冬天\"，是震荡，是垃圾时间，不值得你把种子撒下去。\n\n承认自己是弱者，承认自己管不住盯盘的手，那就交给系统去管。这不可耻，这才是聪明。",
