     "id": "c9",
     "q": "我每次都告诉自己止损，但每次都扛单扛到爆仓，怎么破？",
     "a": "这个问题，你问出来的时候，我就知道你已经被自己折磨很久了。\n\n你不是不知道要止损，你是\"知道\"但\"做不到\"。这两个之间，隔著一条很深很深的鸿沟。几乎所有亏大钱的人，都是死在这条沟里。\n\n为什么做不到？因为你止损的那一刻，你要承认自己错了。没有人喜欢承认自己错了。你会想：再等等，万一回来了呢？结果越等越远，越远越不舍得割，最后破罐子破摔。\n\n我跟你说句扎心的话：你扛的不是单，是你的自尊心。\n\n你接受不了那一笔小小的亏损，结果最后被迫接受一笔大到让你怀疑人生的亏损。你仔细想想，是不是每次爆仓前，都有无数次可以小亏离场的机会？你都没走。\n\nDCOGAI 的纠错系统，解决的就是这个问题。它不是帮你判断行情，是替你去执行那个你下不去手的止损。行情一不对，它马上分层减仓、纠错离场，绝不含糊。\n\n它不是比你聪明，它是比你\"无情\"。它不会心疼钱，不会觉得没面子，不会想\"万一\"。它只知道：错了就走，保住剩下的子弹。\n\n这就是\"弱者道之用\"。承认自己在止损这件事上是个弱者，承认自己下不去手，那就把这个决定交给一个下得去手的系统。你不需要战胜人性，你只需要承认你有这个人性，然后让没有情绪的系统替你去执行。",
