     "a": "姐姐聽到這句話，心裡其實有點疼。因為說這句話的人，往往已經扛了很久了。\n\n姐姐想請你做一件事：打開帳戶，看一眼那個數字。它不會因為你不看、不承認，就變得好起來。\n\n「我不賣就不是虧」——這句話最大的問題，不是它不對，而是它讓你把「不面對」當成了「沒發生」。\n\n虧了就是虧了。數字就在那裡。你賣不賣，它都在。你唯一能選的，不是「要不要承認虧」，而是「這個虧，我打算怎麼處理」。\n\n有人會說：那我賣了，就真的虧了；我不賣，還有機會漲回來。\n\n姐姐懂。但「有機會漲回來」和「一定會漲回來」，是兩回事。你留著它，是基於「它會回來」的判斷，還是基於「我不想承認虧損」的害怕？\n\n如果是後者，那姐姐要說句扎心的話：你現在不是在守倉位，你是在躲那個數字。\n\n真正成熟的交易者，不是不怕虧。是虧了之後，能面不改色地處理它，然後繼續做下一筆。",
     "keywords": [
      "我不賣就不是虧",
      "損失厭惡",
      "浮虧也是虧"
     ]
