     "a": "姐姐先抱抱你。這種「不做點什麼就難受」的感覺，姐姐太懂了——它像手裡握著個燙東西，總想快點丟出去。\n\n但你發現沒有：你現在做的那些「點什麼」，真的是交易需要的嗎？\n\n還是說，你只是太難受了，想用「動手」來緩解那種難受？\n\n姐姐見過很多這樣的朋友：虧了，難受，然後開一單，以為能轉移注意力；結果那一單又虧了，更難受，然後再開一單……最後帳戶裡滿是「為了不難受」開出來的單子。\n\n這就叫情緒替代——你不是在交易，你是在用交易止痛。可交易從來不是止痛藥，它是放大鏡。你帶著情緒進場，它會把你的情緒放大給你看。\n\n姐姐想請你做一個小小的約定：下次覺得「不做點什麼就難受」的時候，先關掉軟體，去喝杯水、走兩步、洗把臉。等那陣難受過去了，再問自己：現在，我還想交易嗎？\n\n如果還想，那是機會。如果不想了——那剛才那個「想」，只是難受在說話。",
